mapper.select:
SELECT id, user_id, sku_id, quantity, created_at, updated_at
FROM cart_item
WHERE user_id = #{userId}
  AND sku_id = #{skuId}

mapper.update:
UPDATE cart_item
SET quantity = #{quantity}, updated_at = CURRENT_TIMESTAMP(3)
WHERE user_id = #{userId}
  AND sku_id = #{skuId}

mapper.delete:
DELETE FROM cart_item
WHERE user_id = #{userId}
  AND sku_id = #{skuId}
